#include <string_view>

bool isPalindrome(std::string_view text)
{
    if (text.length() <= 1)
    {
        return true;
    }
    if (text.front() != text.back())
    {
        return false;
    }
    return isPalindrome(text.substr(1, text.length() - 2));
}

